mapper.sql:
FROM user_account u LEFT JOIN user_profile p ON p.user_id=u.id LEFT JOIN major m ON m.id=p.major_id
    AND (u.nickname ILIKE '%'||#{keyword}||'%' OR u.account_code ILIKE '%'||#{keyword}||'%' OR u.email_key ILIKE '%'||#{keyword}||'%')
    AND coalesce(p.college_id,m.college_id)=#{collegeId}AND p.major_id=#{majorId}AND u.status=#{status}
